/**
 * Controls whether Biome keeps, adds, or removes line breaks in Markdown paragraphs.
 *
 * Manual line breaks are always kept. In Markdown, a manual line break is created by ending a
 * line with two spaces or a backslash.
 *
 * @schema ProseWrap
 */
export enum ProseWrap {
  /** Keep line breaks as written in the source file. This is the default. (preserve) */
  PRESERVE = "preserve",
  /** Wrap paragraphs to fit the configured `lineWidth`. (always) */
  ALWAYS = "always",
  /** Remove line breaks from paragraphs so that each paragraph is on one line. (never) */
  NEVER = "never",
}
